//! Golden values for the built-in functions: `tests/data/p1_goldens.tsv`
//! lists a formula over literals, the expected value (from LibreOffice
//! 25.8 headless, regenerated by `scripts/goldens/p1.py`, or from the
//! Excel/Gnumeric/Numbers/Quantrix documentation where LibreOffice lacks the
//! function), and its source. Each formula runs through BOTH the scalar
//! evaluator and the dataflow engine.

use improv_core_model::{Measure, MeasureId, MeasureKind, Model, Name, ValueType};
use improv_engine::{dataflow::evaluate, scalar, CellValue};
use std::collections::HashMap;

/// The expected column: a JSON number, string, bool, or `{"error": "#NUM!"}`.
fn expected(j: &serde_json::Value) -> CellValue {
    match j {
        serde_json::Value::Number(n) => CellValue::num(n.as_f64().unwrap()),
        serde_json::Value::String(s) => CellValue::Text(s.clone()),
        serde_json::Value::Bool(b) => CellValue::Bool(*b),
        serde_json::Value::Object(o) => {
            let code = o["error"].as_str().unwrap();
            let kind = improv_core_model::ValueErrorKind::from_code(code)
                .unwrap_or_else(|| panic!("unknown error {code}"));
            CellValue::Err(kind.error_type().unwrap())
        }
        other => panic!("bad expected value {other}"),
    }
}

/// Equal, or numbers within 1e-12 relative (transcendental functions may
/// differ from LibreOffice's in the last bits).
fn close(got: &CellValue, want: &CellValue) -> bool {
    match (got.as_num(), want.as_num()) {
        (Some(a), Some(b)) => a == b || (a - b).abs() <= 1e-12 * b.abs().max(1e-300),
        _ => got == want,
    }
}

#[test]
fn builtins_match_the_goldens() {
    let text = include_str!("data/p1_goldens.tsv");
    let model = Model::new();
    let mut failures = Vec::new();
    let mut checked = 0;
    for (n, line) in text.lines().enumerate().skip(1) {
        let mut cols = line.splitn(3, '\t');
        let (Some(formula), Some(want), Some(source)) = (cols.next(), cols.next(), cols.next())
        else {
            continue;
        };
        let want = expected(
            &serde_json::from_str(want)
                .unwrap_or_else(|e| panic!("line {}: bad JSON {want:?}: {e}", n + 1)),
        );
        let expr = match improv_core_model::parse_expr(&model, formula) {
            Ok(f) => f.expr,
            Err(e) => {
                failures.push(format!("line {}: {formula}: parse error {e}", n + 1));
                continue;
            }
        };
        let got = scalar::eval(&expr, &HashMap::new());
        match got {
            Ok(Some(v)) if close(&v, &want) => {}
            other => {
                failures.push(format!(
                    "line {}: {formula} = {other:?}, want {want} ({source})",
                    n + 1
                ));
                continue;
            }
        }
        checked += 1;
    }
    assert!(checked > 500, "only {checked} goldens checked");
    assert!(
        failures.is_empty(),
        "{} of {} goldens fail:\n{}",
        failures.len(),
        checked + failures.len(),
        failures.join("\n")
    );
}

/// The dataflow gives the same values as the scalar evaluator for every
/// golden (one dimensionless model, a measure per formula).
#[test]
fn dataflow_matches_scalar_on_the_goldens() {
    let text = include_str!("data/p1_goldens.tsv");
    let mut model = Model::new();
    let mut want = HashMap::new();
    for (n, line) in text.lines().enumerate().skip(1) {
        let formula = line.split('\t').next().unwrap();
        let Ok(f) = improv_core_model::parse_expr(&model, formula) else {
            continue;
        };
        let Ok(Some(v)) = scalar::eval(&f.expr, &HashMap::new()) else {
            continue;
        };
        let Ok(typed) = improv_engine::compiler::infer(
            &improv_engine::compiler::CompileContext::new(&model.measures),
            MeasureId(0),
            &f.expr,
        ) else {
            continue;
        };
        let id = MeasureId(1000 + n as u32);
        model.add_measure(Measure {
            id,
            name: Name(format!("G{n}")),
            value_type: typed.ty.value_type,
            categories: vec![],
            kind: MeasureKind::Derived(f),
            description: None,
        });
        want.insert(id, v);
    }
    let ids: Vec<MeasureId> = want.keys().copied().collect();
    let out = evaluate(&model, &ids).expect("evaluate");
    for (id, v) in &want {
        let got = out.get(id).and_then(|m| m.get(&Vec::new()));
        assert_eq!(got, Some(v), "{}", model.measures[id].name.0);
    }
    assert!(want.len() > 500);
    let _ = ValueType::Number;
}
